update pages set contenu = '{"sections":[{"type":"heros","h1":"Réparation vérin hydraulique","mecanisme":"Nous venons voir le vérin en charge, sur votre site, avant de décider quoi que ce soit. Inspection complète, kit de joints, guidage repris, essais en pression avant de vous rendre la machine. La réparation remplace presque toujours la commande d''un vérin neuf.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"+ 80","libelle":"clients réguliers, beaucoup arrivés par une panne"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"}]},{"type":"probleme","punchline":"Un vérin qui fuit, c''est une presse arrêtée et un devis de remplacement posé sur votre bureau le lendemain.","puces":[{"accroche":"Personne ne prend le temps d''inspecter.","texte":"Le vérin part à la benne, un neuf est commandé, et le délai de fabrication immobilise la machine plusieurs semaines."},{"accroche":"La fuite interne ne se voit pas.","texte":"Le vérin descend seul sous charge, sans une goutte au sol. On démonte le mauvais composant et la panne revient."},{"accroche":"La tige rayée détruit les joints neufs.","texte":"Le chrome éclaté par un choc ou la corrosion, et votre réparation tient quelques jours."},{"accroche":"Le remontage fait vite coûte deux fois.","texte":"Une bague montée de travers, un couple de serrage approximatif, et la machine repart pour un tour d''arrêt."}]},{"type":"offre","lignes":[{"prestation":"**Un diagnostic fait sur votre site** : nous venons voir le vérin en charge, pas sur photo. Mesure de la perte de pression, analyse du fluide, contrôle du débit de pompe.","benefice":"La cause est identifiée avant le démontage. Vous ne payez pas la dépose d''un composant sain."},{"prestation":"**Un démontage propre** : consignation, pression résiduelle retirée, charge calée, orifices obturés. Démontage à l''établi, jamais au marteau.","benefice":"Le vérin ne sort pas plus abîmé qu''il n''est entré. Et personne ne se blesse sous une charge non calée."},{"prestation":"**Une inspection sérieuse avant toute commande** : alésage mesuré, rectitude de la barre chromée, tige de piston, portées, guidage.","benefice":"Vous savez ce qui est réellement mort avant d''engager la moindre pièce."},{"prestation":"**Un arbitrage honnête entre réparation, usinage et fabrication** : nous ne sommes ni fabricant de vérins ni atelier d''usinage.","benefice":"Aucun intérêt à vous vendre du neuf. Nous vous disons quand le corps est voilé et quand un kit de joints suffit."},{"prestation":"**Un remontage au couple, en atelier propre** : kit complet, bagues de guidage neuves, graissage des pièces, contrôle de course à vide.","benefice":"La moitié des retours en panne vient d''un remontage bâclé. Cette cause-là disparaît."},{"prestation":"**Des essais avant de vous rendre la machine** : mise en pression par paliers, course complète, étanchéité, tenue sous effort nominal.","benefice":"Un vérin réparé se prouve. Vous ne relancez pas la production sur une promesse."},{"prestation":"**Un compte rendu écrit** : cause de la défaillance, mesures relevées, référence des pièces, photos de montage.","benefice":"Plus de discussion au prochain incident, et votre service maintenance garde la trace."}],"prose":[{"texte":"Le vérin n''est souvent que le symptôme : une huile chargée ou une pompe fatiguée le tuera à nouveau. Le circuit complet relève de notre [maintenance hydraulique](/expertises/hydraulique/). Presse à l''arrêt en ce moment, c''est du [dépannage industriel](/offres/depannage-industriel/). Et si le même vérin vous lâche pour la troisième fois, regardez l''abonnement [Zéro arrêt](/offres/zero-arret/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez le symptôme","texte":"type de vérin, machine, ce que vous voyez. Fuite à la tête, descente sous charge, perte de force, course incomplète. Quelques minutes au téléphone évitent un déplacement pour rien."},{"titre":"Un technicien vous rappelle dans l''heure.","texte":"Vous savez tout de suite si le vérin se traite en place ou s''il faut le déposer."},{"titre":"Nous cherchons la cause avant de démonter","texte":"essai de pression pour isoler le vérin du circuit, analyse de l''huile, écoute de la pompe."},{"titre":"Nous déposons et nous inspectons.","texte":"Vous recevez le constat pièce par pièce, avec le prix et le délai réels, avant tout engagement de travaux."},{"titre":"Nous réparons, puis nous essayons","texte":"joints, guidage, reprise de tige si le chrome le permet. Essai en pression et en effort, banc du spécialiste pour les gros vérins."},{"titre":"Nous reposons et nous remettons en service","texte":"purge, réglage des vitesses, essai de production avec vos opérateurs, compte rendu écrit avant de quitter le site."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Aucune vente de matériel, aucune fabrication maison.","texte":"Nous ne remplissons aucun carnet de commandes : quand la réparation est perdue d''avance, corps fendu ou machine en fin de vie, nous vous le disons au lieu de facturer des travaux inutiles."},{"accroche":"Le vérin n''est rendu qu''après vérification écrite.","texte":"Course franche dans les deux sens, aucune trace sous pression à l''arrêt, charge nominale tenue, mesures consignées. Démarche MASE et évaluation EcoVadis, attestations transmises avec chaque plan de prévention."}]},{"type":"cta","question":"Besoin de faire réparer un vérin avant de commander un neuf ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Dépannage de presses hydrauliques et mécaniques, pièces mécaniques de précision","texte":"un technicien intégré à temps plein, périmètre centres d''usinage grande vitesse, presses automatisées et commande numérique, parc multimarques, 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Maintien opérationnel de convoyeurs, trieurs et packaging automatisés, logistique et transport","texte":"deux techniciens en poste, hydraulique parmi les domaines couverts en propre","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Contrat de maintenance préventive annuelle, logistique","texte":"six techniciens polyvalents en permanence, hydraulique comprise dans les domaines couverts, depuis septembre 2023","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Montages, déplacements de machines et renfort technique, étanchéité et isolation","texte":"profils assemblés selon le chantier, hydraulique parmi les domaines mobilisables, sur l''année 2025","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"},{"titre":"Maintenance sous contrat d''un parc déployé partout en France, réalité virtuelle","texte":"périmètre technique complet, hydraulique comprise, depuis février 2024","lienLibelle":"Étude de cas TIMESCOPE : casques de réalité virtuelle","lienHref":"/preuves/timescope/"}]},{"type":"objections","questions":[{"question":"Peut-on réparer un vérin sans le déposer ?","reponse":"Une reprise d''étanchéité de tige est parfois possible en place, sur la machine. Dès que le piston ou le guidage est en cause, la dépose devient nécessaire pour un travail fiable. Le diagnostic sur site tranche cette question en premier, parce qu''elle conditionne tout le reste : la durée d''immobilisation, le coût, et le besoin ou non d''un atelier."},{"question":"Réparer coûte-t-il vraiment moins cher que remplacer ?","reponse":"Dans la grande majorité des cas, oui, et pour une fraction du prix du neuf. Trois situations font basculer l''arbitrage : un corps voilé ou fendu, un vérin obsolète dont la barre chromée n''existe plus au bon diamètre, et un équipement promis à la casse. Nous vous le disons quand la réparation n''est pas le bon choix. Nous ne fabriquons pas de vérins, nous n''avons rien à gagner à vous vendre du neuf."},{"question":"Faut-il changer tous les joints ou seulement celui qui lâche ?","reponse":"Toujours le kit complet. Remplacer un seul joint sur un vérin déjà démonté revient à programmer la prochaine intervention, sur une machine qu''il faudra arrêter une deuxième fois. Le surcoût d''un kit face à un joint isolé est sans rapport avec le coût d''un second arrêt."},{"question":"Comment savoir si la tige doit être rechromée ?","reponse":"Une tige piquée ou rayée en profondeur détruit des joints neufs en quelques jours. Nous la mesurons au comparateur et nous contrôlons l''état du chrome. Si le corps est sain et que seule la tige est marquée, une reprise d''usinage et un traitement de surface suffisent, chez un atelier spécialisé que nous pilotons. Sinon, nous comparons avec le coût d''une tige neuve avant de décider."},{"question":"Intervenez-vous sur des vérins de grande dimension ?","reponse":"Oui, avec les moyens de manutention adaptés au poids. Vérins de presse et de formage, gros diamètres, efforts élevés. Les essais des grandes pièces se font sur le banc du spécialiste, sous notre contrôle, avec mise en pression par paliers et contrôle de la charge nominale. Nous traitons aussi le vérin simple effet, le double effet, le télescopique et le pneumatique, toutes marques."},{"question":"Couvrez-vous notre région ?","reponse":"Oui. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et 10 hubs de techniciens à Paris, Lille, Marseille, Toulouse, Lyon, Metz, Strasbourg, Bordeaux, Dijon et Nantes. Nos techniciens sont mobiles, y compris hors de ces villes. Notre accueil téléphonique oriente votre besoin vers l''expert le plus proche, et vous rappelle dans l''heure."}]},{"type":"ctaFinal","question":"Besoin qu''un technicien voie votre vérin en charge avant que la décision soit prise à votre place ?","bouton":"Demander une intervention"}]}'::jsonb where path = '/expertises/hydraulique/verin-hydraulique/';
